        "other_attributes": {
            "description": "Use for other licence attributes for which we don't yet have curated schema attributes",
            "type": "object"
        }
    },
    "additionalProperties": false,
    "required": [
        "source_url",
        "sample_date",
        "licence_holder",
        "permissions",
        "licence_issuer",
        "jurisdiction_of_licence"
    ],
    "definitions": {
