{
    "id": "https://raw.githubusercontent.com/rolfvreijdenberger/jsend-json-schema/master/jsend-json-schema.json",
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "jsend json schema",
    "description": "This is a json-schema for the jsend format for json responses for applications. see https://labs.omniti.com/labs/jsend/wiki",
    "type": "object",
    "oneOf": [
        {
            "$ref": "#/definitions/success"
        },
        {
            "$ref": "#/definitions/fail"
        },
        {
            "$ref": "#/definitions/error"
        }
    ],
    "definitions": {
        "success": {
            "description": "All went well, and (usually) some data was returned.",
            "required": [
                "status",
                "data"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "pattern": "^success$",
                    "description": "the status for a succesful handling"
                },
                "data": {
                    "description": "Acts as the wrapper for any data returned by the API call. If the call returns no data (as in the last example), data should be set to null.",
                    "$ref": "#/definitions/data"
                }
            }
        },
        "fail": {
            "description": "There was a problem with the data submitted, or some pre-condition of the API call wasn't satisfied",
            "required": [
                "status",
                "data"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "pattern": "^fail$",
                    "description": "the status for a failure handling"
                },
                "data": {
                    "description": "provides the wrapper for the details of why the request failed. If the reasons for failure correspond to POST values, the response object's keys SHOULD correspond to those POST values.",
                    "$ref": "#/definitions/data"
                }
            }
        },
        "error": {
            "description": "An error occurred in processing the request, i.e. an exception was thrown",
            "required": [
                "status",
                "message"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "pattern": "^error$",
                    "description": "the status for a error handling"
                },
                "message": {
                    "$ref": "#/definitions/message"
                },
                "code": {
                    "$ref": "#/definitions/code"
                },
                "data": {
                    "description": "A generic container for any other information about the error, i.e. the conditions that caused the error, stack traces, etc.",
                    "$ref": "#/definitions/data"
                }
            }
        },
        "data": {
            "description": "a generic container for data returned for success, fail or error",
            "type": [
                "string",
                "null",
                "array",
                "object",
                "integer",
                "boolean"
            ]
        },
        "code": {
            "description": "A numeric code corresponding to the error in an error result, if applicable",
            "type": [
                "string",
                "integer"
            ]
        },
        "message": {
            "description": "A meaningful, end-user-readable (or at the least log-worthy) message, explaining what went wrong in an error result.",
            "type": "string"
        }
    }
}

{
    "gear": {
        "name": "fsl-sienax",
        "label": "FSL: SIENAX - Brain tissue volume, normalised for subject head size",
        "description": "FSL's SIENAX. Sienax estimates total brain tissue volume, from a single image, normalised for skull size. It calls a series of FSL programs: It first strips non-brain tissue, and then uses the brain and skull images to estimate the scaling between the subject's image and standard space. It then runs tissue segmentation to estimate the volume of brain tissue, and multiplies this by the estimated scaling factor, to reduce head-size-related variability between subjects. Inputs should be structural image (T1-weighted, T2-weighted, PD, etc) where the in-plane resolution is better than 2mm (ideally 1mm). Outputs consist of an archive containing the results of the analysis, as well as an HTML report summarizing the analysis findings.",
        "author": "Analysis Group, FMRIB, Oxford, UK.",
        "maintainer": "Flywheel <support@flywheel.io>",
        "license": "Apache-2.0",
        "url": "https://fsl.fmrib.ox.ac.uk/fsl/fslwiki/SIENA",
        "source": "https://github.com/flywheel-apps/fsl-siena-sienax",
        "cite": "S.M. Smith, Y. Zhang, M. Jenkinson, J. Chen, P.M. Matthews, A. Federico, and N. De Stefano. Accurate, robust and automated longitudinal and cross-sectional brain change analysis. NeuroImage, 17(1):479-489, 2002.  S.M. Smith, M. Jenkinson, M.W. Woolrich, C.F. Beckmann, T.E.J. Behrens, H. Johansen-Berg, P.R. Bannister, M. De Luca, I. Drobnjak, D.E. Flitney, R. Niazy, J. Saunders, J. Vickers, Y. Zhang, N. De Stefano, J.M. Brady, and P.M. Matthews. Advances in functional and structural MR image analysis and implementation as FSL. NeuroImage, 23(S1):208-219, 2004.",
        "version": "1.0.1_5.0",
        "custom": {
            "flywheel": {
                "suite": "FSL"
