                            "type": {
                                "enum": [
                                    "text"
                                ]
                            }
                        }
                    },
                    "NIFTI": {
                        "type": "object",
                        "properties": {
                            "type": {
                                "enum": [
                                    "nifti"
                                ]
                            }
                        }
                    }
                }
            },
            "config": {
                "required": [
                    "NOISE_LVL",
                    "HPF_CUTOF",
                    "INT_NORM",
                    "MC",
                    "STC",
                    "T_SMOOTH",
                    "REG_STANDARD_IMAGE",
                    "Z_THRESH",
                    "BB_THRESH",
                    "LPF",
                    "FWHM",
                    "HPF",
                    "BET"
                ],
                "type": "object",
                "properties": {
                    "NOISE_LVL": {
                        "default": 0.66,
                        "type": "number"
                    },
                    "HPF_CUTOF": {
                        "default": 100,
                        "type": "number"
                    },
                    "INT_NORM": {
                        "default": 1,
                        "minimum": 0,
                        "type": "integer",
                        "maximum": 1
                    },
                    "MC": {
                        "default": 1,
                        "minimum": 0,
                        "type": "integer",
                        "maximum": 1
                    },
                    "STC": {
                        "default": 1,
                        "type": "integer"
                    },
                    "T_SMOOTH": {
                        "default": 0.34,
                        "type": "number"
                    },
                    "REG_STANDARD_IMAGE": {
                        "default": 0,
                        "minimum": 0,
                        "type": "integer",
                        "maximum": 1
                    },
                    "Z_THRESH": {
                        "default": 5.3,
                        "type": "number"
